// Build a Discord rich embed for a PUSH event.
const e = $input.first().json.body;
const m = e.meta || {};
const clip = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + '…' : s);
let color = 3066993, emoji = '📦';
if (m.deleted)      { color = 15158332; emoji = '🗑️'; }
else if (m.created) { color = 3447003;  emoji = '🌱'; }
else if (m.forced)  { color = 15844367; emoji = '⚠️'; }
const fields = [
  { name: 'Repository', value: e.repo.name, inline: true },
  { name: m.refKind === 'tag' ? 'Tag' : 'Branch', value: m.ref || '—', inline: true },
  { name: 'Commits', value: String(m.commitCount ?? 0), inline: true },
];
const embed = { title: clip(`${emoji} ${e.title}`, 256), url: e.url, color,
  author: { name: e.actor.login, url: e.actor.url, icon_url: e.actor.avatar || undefined },
  description: e.body ? clip(e.body, 4000) : undefined, fields,
  footer: { text: 'RepoRadar • push' }, timestamp: new Date().toISOString() };
return [{ json: { username: 'RepoRadar', embeds: [embed] } }];

// Build a Discord rich embed for a PULL_REQUEST event.
const e = $input.first().json.body;
const m = e.meta || {};
const a = e.action;
const clip = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + '…' : s);
let color, emoji;
if (a === 'merged')                          { color = 3066993;  emoji = '🟣'; }
else if (a === 'closed')                     { color = 15158332; emoji = '🔴'; }
else if (a === 'opened' || a === 'reopened') { color = 5793266;  emoji = '🔀'; }
else                                         { color = 9807270;  emoji = '🔀'; }
const fields = [
  { name: 'Repository', value: e.repo.name, inline: true },
  { name: 'Flow', value: `\`${m.head}\` → \`${m.base}\``, inline: true },
];
if (m.additions != null || m.deletions != null) {
  const files = m.changedFiles != null ? ` (${m.changedFiles} files)` : '';
  fields.push({ name: 'Changes', value: `+${m.additions ?? 0} / -${m.deletions ?? 0}${files}`, inline: true });
}
if (m.draft) fields.push({ name: 'Status', value: 'Draft', inline: true });
const embed = { title: clip(`${emoji} ${e.title}`, 256), url: e.url, color,
  author: { name: e.actor.login, url: e.actor.url, icon_url: e.actor.avatar || undefined },
  description: e.body ? clip(e.body, 4000) : undefined, fields,
  footer: { text: `RepoRadar • pull request • ${a}` }, timestamp: new Date().toISOString() };
return [{ json: { username: 'RepoRadar', embeds: [embed] } }];

// Build a Discord rich embed for an ISSUES event.
const e = $input.first().json.body;
const m = e.meta || {};
const a = e.action;
const clip = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + '…' : s);
let color, emoji;
if (a === 'opened')        { color = 15158332; emoji = '🐛'; }
else if (a === 'reopened') { color = 15105570; emoji = '🔄'; }
else if (a === 'closed')   { color = 3066993;  emoji = '✅'; }
else if (a === 'labeled' || a === 'unlabeled') { color = 10181046; emoji = '🏷️'; }
else                       { color = 9807270;  emoji = '📝'; }
const labels = Array.isArray(m.labels) && m.labels.length ? m.labels.join(', ') : '—';
const fields = [
  { name: 'Repository', value: e.repo.name, inline: true },
  { name: 'State', value: m.state || '—', inline: true },
  { name: 'Labels', value: labels, inline: false },
];
if (m.changedLabel) fields.splice(2, 0, { name: 'Changed label', value: m.changedLabel, inline: true });
const embed = { title: clip(`${emoji} ${e.title}`, 256), url: e.url, color,
  author: { name: e.actor.login, url: e.actor.url, icon_url: e.actor.avatar || undefined },
  description: e.body ? clip(e.body, 4000) : undefined, fields,
  footer: { text: `RepoRadar • issue • ${a}` }, timestamp: new Date().toISOString() };
return [{ json: { username: 'RepoRadar', embeds: [embed] } }];

// Runs ONLY when "Send to Discord" fails after all retries.
// Discord webhooks return 429 with { retry_after } (seconds) + Retry-After header.
// Native retry (5x, 3s backoff) covers transient 429/5xx; this branch handles
// the rare case where delivery still fails, so we log a diagnostic and reply 502.
const item = $input.first().json || {};
const err = item.error || item;
const resp = err.response || err.context || {};
const status = resp.statusCode || resp.status || err.httpCode || err.code || null;
let retryAfter = null;
try {
  const body = resp.body || resp.data || {};
  const headers = resp.headers || {};
  retryAfter = body.retry_after ?? headers['retry-after'] ?? null;
} catch (_) {}
const diagnostic = {
  ok: false,
  stage: 'discord_delivery',
  status,
  retryAfter,
  message: err.message || 'Discord delivery failed after retries',
  at: new Date().toISOString(),
};
// Surfaces in n8n execution logs for the case-study / debugging.
console.error('[RepoRadar] Discord delivery failed:', JSON.stringify(diagnostic));
return [{ json: diagnostic }];
